source3 = '''def transform(grid):
    grid = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    sep_rows = [r for r, row in enumerate(grid) if row[0] != 0 and all(x == row[0] for x in row)]
    sep_cols = [c for c in range(w) if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]
    rb = [-1] + sep_rows + [h]
    cb = [-1] + sep_cols + [w]
    rs = [(rb[i] + 1, rb[i + 1]) for i in range(len(rb) - 1)]
    cs = [(cb[i] + 1, cb[i + 1]) for i in range(len(cb) - 1)]
    nr, nc = len(rs), len(cs)

    def tile(r, c, board=grid):
        r0, r1 = rs[r]
        c0, c1 = cs[c]
        return [row[c0:c1] for row in board[r0:r1]]

    def color(r, c, board=grid):
        vals = {v for row in tile(r, c, board) for v in row if v != 0}
        return next(iter(vals)) if len(vals) == 1 else None

    def put(r, c, value):
        r0, r1 = rs[r]
        c0, c1 = cs[c]
        for i, row in enumerate(value):
            for j, v in enumerate(row):
                grid[r0 + i][c0 + j] = v

    # Select the tightest 2-by-2 patch containing repeated copies of one motif.
    candidates = []
    for r0 in range(nr - 1):
        for c0 in range(nc - 1):
            positions = [(r, c) for r in (r0, r0 + 1) for c in (c0, c0 + 1)]
            present = [(r, c, color(r, c)) for r, c in positions if color(r, c) is not None]
            if len(present) >= 2 and len({x[2] for x in present}) == 1:
                candidates.append((len(present), r0, c0, present[0][2], positions, present))
    best = {}
    for candidate in candidates:
        count, _, _, col, _, _ = candidate
        best[col] = max(best.get(col, 0), count)
    for count, r0, c0, col, positions, present in candidates:
        if count != best[col]:
            continue
        for r, c in positions:
            if color(r, c) is not None:
                continue
            sr, sc, _ = min(present, key=lambda p: abs(p[0] - r) + abs(p[1] - c))
            src = tile(sr, sc)
            if sr != r:
                src = src[::-1]
            if sc != c:
                src = [line[::-1] for line in src]
            dst = tile(r, c)
            if len(src) == len(dst) and all(len(a) == len(b) for a, b in zip(src, dst)):
                put(r, c, src)
    return grid
'''
